# GENERATED by codegen/e2e_bridge.py (codegen/e2e_bview_gen.py). Do not edit.
# The bit-list decoders' objects against the codec laws' value bits: the decoder copies the list's
# words, zeroes the bytes past n in the last word (mask_last) and clears the delimiter bit NB
# (clear_bit); neither touches the first NB bits (mlb, clr: a word AND a mask whose first p bits are
