MASK = r'''
# ---- mask_last: the last word keeps its first (n & 3) bytes ----

law btk_rep:
  for +p: Nat
  for +a: Nat
  for +R: +List<Bool>
  for +h: {Nat.is_le(p, a) == True{} : Bool}
  {BK.btk(p, List.append(&2, Bool, rep(a), R)) == rep(p) : +List<Bool>}
def btk_rep(p, a, R, h):
  match p a:
    case 0n _: {==}
    case 1n+ +k 0n: Empty.absurd({BK.btk(1n+k, List.append(&2, Bool, rep(0n), R)) == rep(1n+k) : +List<Bool>}, FD.logic__false_true(h))
    case 1n+ +k 1n+ +b: Equal.cong(+List<Bool>, +List<Bool>, z => True{} <> z, BK.btk(k, List.append(&2, Bool, rep(b), R)), rep(k), btk_rep(k, b, R, h))

def zb(+k: Nat) -> +List<Bool>:
  match k:
    case 0n: []
    case 1n+p: False{} <> zb(p)

# keep(r, x) has x's first 8 r bits (r = 1, 2, 3).
def kp1(+x: U32, +p: Nat, +hp: {Nat.is_le(p, 8n) == True{} : Bool}) -> {BK.btk(p, BLf.wbits(O.keep(1, x))) == BK.btk(p, BLf.wbits(x)) : +List<Bool>}:
  akU(x, 255, p, btk_rep(p, 8n, zb(24n), hp))
def kp2(+x: U32, +p: Nat, +hp: {Nat.is_le(p, 16n) == True{} : Bool}) -> {BK.btk(p, BLf.wbits(O.keep(2, x))) == BK.btk(p, BLf.wbits(x)) : +List<Bool>}:
  akU(x, 65535, p, btk_rep(p, 16n, zb(16n), hp))
def kp3(+x: U32, +p: Nat, +hp: {Nat.is_le(p, 24n) == True{} : Bool}) -> {BK.btk(p, BLf.wbits(O.keep(3, x))) == BK.btk(p, BLf.wbits(x)) : +List<Bool>}:
  akU(x, 16777215, p, btk_rep(p, 24n, zb(8n), hp))

def mlt(whole: Bool, +rem: U32, +q: Nat, +d: Nat, +T: FD.array__Tree<U32>) -> FD.array__Tree<U32>:
  match whole:
    case True{}: T
    case False{}: FD.array__upd(U32, d, T, q, O.keep(rem, FD.flat__nthc(FD.array__slots(U32, T), q)))

def mlg(+whole: Bool, +rem: U32, +i: U32, +q: Nat, +d: Nat, +T: FD.array__Tree<U32>, +pf: {FD.array__perfect(U32, d, T) == True{} : Bool},
    +hd: {Nat.is_lt(d, 32n) == True{} : Bool}, +eqi: {U32.to_nat(i) == q : Nat}, +hq: {Nat.is_lt(q, FD.spec_common__pow2(d)) == True{} : Bool})
    -> {O.ml_go(whole, rem, i, FD.array__thaw(U32, T)) == FD.array__thaw(U32, mlt(whole, rem, q, d, T)) : Array<U32>}:
  match whole:
    case True{}: {==}
    case False{}:
      +hi = FD.logic__subst(Nat, z => {Nat.is_lt(z, FD.spec_common__pow2(d)) == True{} : Bool}, q, U32.to_nat(i), Equal.sym(Nat, U32.to_nat(i), q, eqi), hq)
      +x = FD.flat__nthc(FD.array__slots(U32, T), U32.to_nat(i))
      +hx = FD.flat__nthc_nth(FD.array__slots(U32, T), U32.to_nat(i), FD.array__len_lt(U32, d, T, U32.to_nat(i), pf, hi))
      %Equal.sym(Array<U32> & U32, Array.get(U32, FD.array__thaw(U32, T), i), (FD.array__thaw(U32, T), x), FD.array__get(U32, d, T, i, x, hd, hi, hx, pf)) :
        {O.ml_set(rem, i, _) == FD.array__thaw(U32, mlt(False{}, rem, q, d, T)) : Array<U32>}
      %Equal.sym(Array<U32>, Array.set(U32, FD.array__thaw(U32, T), i, O.keep(rem, x)), FD.array__thaw(U32, FD.array__upd(U32, d, T, U32.to_nat(i), O.keep(rem, x))), FD.array__set(U32, d, T, i, O.keep(rem, x), x, hd, hi, hx, pf)) :
        {_ == FD.array__thaw(U32, mlt(False{}, rem, q, d, T)) : Array<U32>}
      %Equal.sym(Nat, U32.to_nat(i), q, eqi) :
        {FD.array__thaw(U32, FD.array__upd(U32, d, T, _, O.keep(rem, FD.flat__nthc(FD.array__slots(U32, T), _)))) == FD.array__thaw(U32, mlt(False{}, rem, q, d, T)) : Array<U32>}
      {==}

def mlp(+whole: Bool, +rem: U32, +q: Nat, +d: Nat, +T: FD.array__Tree<U32>, +pf: {FD.array__perfect(U32, d, T) == True{} : Bool})
    -> {FD.array__perfect(U32, d, mlt(whole, rem, q, d, T)) == True{} : Bool}:
  match whole:
    case True{}: pf
    case False{}: FD.array__upd_perfect(U32, d, T, q, O.keep(rem, FD.flat__nthc(FD.array__slots(U32, T), q)), pf)

# The masked tree keeps the first 32 q + p bits, p <= 8 rem.
def mlb(+rem: U32, +q: Nat, +p: Nat, +d: Nat, +T: FD.array__Tree<U32>, +pf: {FD.array__perfect(U32, d, T) == True{} : Bool},
    +hq: {Nat.is_lt(q, FD.spec_common__pow2(d)) == True{} : Bool}, +hp: {Nat.is_le(p, 32n) == True{} : Bool},
    +hk: {BK.btk(p, BLf.wbits(O.keep(rem, FD.flat__nthc(FD.array__slots(U32, T), q)))) == BK.btk(p, BLf.wbits(FD.flat__nthc(FD.array__slots(U32, T), q))) : +List<Bool>})
    -> {BK.btk(Nat.add(x32(q), p), BK.bitsof(FD.array__slots(U32, mlt(False{}, rem, q, d, T)))) == BK.btk(Nat.add(x32(q), p), BK.bitsof(FD.array__slots(U32, T))) : +List<Bool>}:
  +v = O.keep(rem, FD.flat__nthc(FD.array__slots(U32, T), q))
  %Equal.sym(List<&2, U32>, FD.array__slots(U32, FD.array__upd(U32, d, T, q, v)), FD.spec_common__update(U32, FD.array__slots(U32, T), q, v), FD.array__upd_slots(U32, d, T, q, v, hq, pf)) :
    {BK.btk(Nat.add(x32(q), p), BK.bitsof(_)) == BK.btk(Nat.add(x32(q), p), BK.bitsof(FD.array__slots(U32, T))) : +List<Bool>}
  bu2(q, p, FD.array__slots(U32, T), v, hp, FD.array__len_lt(U32, d, T, q, pf, hq), hk)
'''



def bytes_text():
    L = ["\n# ---- words and bytes: the bits of a word list are the bits of its bytes ----\n",
         "def bb(bs: +List<U32>) -> +List<Bool>:\n  match bs:\n    case Nil{}: []\n    case Con{+h, t}: List.append(&2, Bool, VY.bits8(h), bb(t))\n"]
    lhs = ' <> '.join(f'a{i}' for i in range(32)) + ' <> R'
    def rhs(k, hole=None):
        el = []
        for i in range(32):
            if i == hole:
                el.append('_')
            elif i < k or i >= 24:
                el.append(f'a{i}')
            else:
                el.append(f'Bool.and(a{i}, True{{}})')
        return ' <> '.join(el) + ' <> R'
    steps = []
    for k in range(24):
        steps.append(f'  %Equal.sym(Bool, Bool.and(a{k}, True{{}}), a{k}, andT(a{k})) : {{{lhs} == {rhs(k, hole=k)} : +List<Bool>}}')
    Y = ['U32.and(x, 255)', 'U32.and(U32.shrn(x, 8n), 255)', 'U32.and(U32.shrn(x, 16n), 255)', 'U32.shrn(x, 24n)']
    R = 'R'
    for y in reversed(Y):
        R = f'List.append(&2, Bool, VY.bits8({y}), {R})'
    L.append(f'''
# A word's 32 bits, then R, are its four bytes' bits, then R.
def wbx(+x: U32, +R: +List<Bool>) -> {{List.append(&2, Bool, BLf.wbits(x), R) == {R} : +List<Bool>}}:
  match x:
    case {W32p}: wbc({', '.join(f'a{i}' for i in range(32))}, R)
''')
    L.insert(1, f'''
def wbc({', '.join(f'+a{i}: Bool' for i in range(32))}, +R: +List<Bool>) -> {{{lhs} == {rhs(0)} : +List<Bool>}}:
''' + '\n'.join(steps) + '\n  {==}\n')
    L.append('''
law wbb:
  for +ws: +List<U32>
  {BK.bitsof(ws) == bb(SF.limbs(ws)) : +List<Bool>}
def wbb(ws):
  match ws:
    case Nil{}: {==}
    case Con{+x, +t}:
      %Equal.sym(+List<Bool>, BK.bitsof(t), bb(SF.limbs(t)), wbb(t)) : {List.append(&2, Bool, BLf.wbits(x), _) == bb(SF.limbs(Con{x, t})) : +List<Bool>}
      wbx(x, bb(SF.limbs(t)))
''')
    return ''.join(L)



def bl_text():
    return f'''
def b8len(+v: U32) -> {{List.length(&2, Bool, VY.bits8(v)) == 8n : Nat}}:
  match v:
    case {W32p}: {{==}}

law vbk:
  for +k: Nat
  for +xs: +List<Bool>
  {{VY.btk(k, xs) == BK.btk(k, xs) : +List<Bool>}}
def vbk(k, xs):
  match k xs:
    case 0n _: {{==}}
    case 1n+ +p Nil{{}}: {{==}}
    case 1n+ +p Con{{+b, +t}}: Equal.cong(+List<Bool>, +List<Bool>, z => b <> z, VY.btk(p, t), BK.btk(p, t), vbk(p, t))

law btbt:
  for +m: Nat
  for +L: +List<U32>
  {{VSP.bt(m, VSP.bt(1n+m, L)) == VSP.bt(m, L) : +List<U32>}}
def btbt(m, L):
  match m L:
    case 0n _: {{==}}
    case 1n+ +k Nil{{}}: {{==}}
    case 1n+ +k Con{{+v, +t}}: Equal.cong(+List<U32>, +List<U32>, z => v <> z, VSP.bt(k, VSP.bt(1n+k, t)), VSP.bt(k, t), btbt(k, t))

law lbt:
  for +m: Nat
  for +L: +List<U32>
  for +hm: {{Nat.is_lt(m, List.length(&2, U32, L)) == True{{}} : Bool}}
  {{VBL.lastb(VSP.bt(1n+m, L)) == VBL.nthb(L, m) : U32}}
def lbt(m, L, hm):
  match m L:
    case _ Nil{{}}: Empty.absurd({{VBL.lastb(VSP.bt(1n+m, Nil{{}})) == VBL.nthb(Nil{{}}, m) : U32}}, FD.nat__lt_zero_absurd(m, hm))
    case 0n Con{{+v, +t}}: {{==}}
    case 1n+ +k Con{{+v, Nil{{}}}}: Empty.absurd({{VBL.lastb(VSP.bt(2n+k, Con{{v, Nil{{}}}})) == VBL.nthb(Con{{v, Nil{{}}}}, 1n+k) : U32}}, FD.nat__lt_zero_absurd(k, hm))
    case 1n+ +k Con{{+v, Con{{+w, +r}}}}: lbt(k, Con{{w, r}}, hm)

# The first 8 m + h bits (h <= 8) of a byte list: its first m bytes' bits, then h bits of byte m.
law bl1:
  for +m: Nat
  for +h: Nat
  for +L: +List<U32>
  for +hh: {{Nat.is_le(h, 8n) == True{{}} : Bool}}
  for +hm: {{Nat.is_lt(m, List.length(&2, U32, L)) == True{{}} : Bool}}
  {{BK.btk(Nat.add(VSP.x8(m), h), bb(L)) == List.append(&2, Bool, bb(VSP.bt(m, L)), BK.btk(h, VY.bits8(VBL.nthb(L, m)))) : +List<Bool>}}
def bl1(m, h, L, hh, hm):
  match m L:
    case _ Nil{{}}: Empty.absurd({{BK.btk(Nat.add(VSP.x8(m), h), bb(Nil{{}})) == List.append(&2, Bool, bb(VSP.bt(m, Nil{{}})), BK.btk(h, VY.bits8(VBL.nthb(Nil{{}}, m)))) : +List<Bool>}}, FD.nat__lt_zero_absurd(m, hm))
    case 0n Con{{+v, +t}}:
      btk_le(h, VY.bits8(v), bb(t), FD.logic__subst(Nat, z => {{Nat.is_le(h, z) == True{{}} : Bool}}, 8n, List.length(&2, Bool, VY.bits8(v)), Equal.sym(Nat, List.length(&2, Bool, VY.bits8(v)), 8n, b8len(v)), hh))
    case 1n+ +k Con{{+v, +t}}:
      +K = Nat.add(VSP.x8(k), h)
      %b8len(v) : {{BK.btk(Nat.add(_, K), List.append(&2, Bool, VY.bits8(v), bb(t))) == List.append(&2, Bool, List.append(&2, Bool, VY.bits8(v), bb(VSP.bt(k, t))), BK.btk(h, VY.bits8(VBL.nthb(t, k)))) : +List<Bool>}}
      %Equal.sym(+List<Bool>, BK.btk(Nat.add(List.length(&2, Bool, VY.bits8(v)), K), List.append(&2, Bool, VY.bits8(v), bb(t))), List.append(&2, Bool, VY.bits8(v), BK.btk(K, bb(t))), btk_ge(VY.bits8(v), bb(t), K)) :
        {{_ == List.append(&2, Bool, List.append(&2, Bool, VY.bits8(v), bb(VSP.bt(k, t))), BK.btk(h, VY.bits8(VBL.nthb(t, k)))) : +List<Bool>}}
      %Equal.sym(+List<Bool>, List.append(&2, Bool, List.append(&2, Bool, VY.bits8(v), bb(VSP.bt(k, t))), BK.btk(h, VY.bits8(VBL.nthb(t, k)))), List.append(&2, Bool, VY.bits8(v), List.append(&2, Bool, bb(VSP.bt(k, t)), BK.btk(h, VY.bits8(VBL.nthb(t, k))))), VBL.appB_assoc(VY.bits8(v), bb(VSP.bt(k, t)), BK.btk(h, VY.bits8(VBL.nthb(t, k))))) :
        {{List.append(&2, Bool, VY.bits8(v), BK.btk(K, bb(t))) == _ : +List<Bool>}}
      Equal.cong(+List<Bool>, +List<Bool>, z => List.append(&2, Bool, VY.bits8(v), z), BK.btk(K, bb(t)), List.append(&2, Bool, bb(VSP.bt(k, t)), BK.btk(h, VY.bits8(VBL.nthb(t, k)))), bl1(k, h, t, hh, hm))

# The value bits of a byte list of length 1 + m: its first m bytes' bits, then the last byte's cut at its high bit.
law bl2:
  for +m: Nat
  for +bs: +List<U32>
  for +hl: {{List.length(&2, U32, bs) == 1n+m : Nat}}
  {{VBL.bl(bs) == List.append(&2, Bool, bb(VSP.bt(m, bs)), BK.btk(VY.hb(VBL.lastb(bs)), VY.bits8(VBL.lastb(bs)))) : +List<Bool>}}
def bl2(m, bs, hl):
  match m bs:
    case _ Nil{{}}: Empty.absurd({{VBL.bl(Nil{{}}) == List.append(&2, Bool, bb(VSP.bt(m, Nil{{}})), BK.btk(VY.hb(VBL.lastb(Nil{{}})), VY.bits8(VBL.lastb(Nil{{}})))) : +List<Bool>}}, FD.nat__succ_zero(m, Equal.sym(Nat, 0n, 1n+m, hl)))
    case 0n Con{{+v, Nil{{}}}}: vbk(VY.hb(v), VY.bits8(v))
    case 0n Con{{+v, Con{{+w, +r}}}}: Empty.absurd({{VBL.bl(Con{{v, Con{{w, r}}}}) == List.append(&2, Bool, bb(VSP.bt(0n, Con{{v, Con{{w, r}}}})), BK.btk(VY.hb(VBL.lastb(Con{{v, Con{{w, r}}}})), VY.bits8(VBL.lastb(Con{{v, Con{{w, r}}}})))) : +List<Bool>}}, FD.nat__succ_zero(List.length(&2, U32, r), FD.nat__succ_inj(1n+List.length(&2, U32, r), 0n, hl)))
    case 1n+ +k Con{{+v, Nil{{}}}}: Empty.absurd({{VBL.bl(Con{{v, Nil{{}}}}) == List.append(&2, Bool, bb(VSP.bt(1n+k, Con{{v, Nil{{}}}})), BK.btk(VY.hb(VBL.lastb(Con{{v, Nil{{}}}})), VY.bits8(VBL.lastb(Con{{v, Nil{{}}}})))) : +List<Bool>}}, FD.nat__succ_zero(k, Equal.sym(Nat, 0n, 1n+k, FD.nat__succ_inj(0n, 1n+k, hl))))
    case 1n+ +k Con{{+v, Con{{+w, +r}}}}:
      +Y = BK.btk(VY.hb(VBL.lastb(Con{{w, r}})), VY.bits8(VBL.lastb(Con{{w, r}})))
      %Equal.sym(+List<Bool>, List.append(&2, Bool, List.append(&2, Bool, VY.bits8(v), bb(VSP.bt(k, Con{{w, r}}))), Y), List.append(&2, Bool, VY.bits8(v), List.append(&2, Bool, bb(VSP.bt(k, Con{{w, r}})), Y)), VBL.appB_assoc(VY.bits8(v), bb(VSP.bt(k, Con{{w, r}})), Y)) :
        {{List.append(&2, Bool, VY.bits8(v), VBL.bl(Con{{w, r}})) == _ : +List<Bool>}}
      Equal.cong(+List<Bool>, +List<Bool>, z => List.append(&2, Bool, VY.bits8(v), z), VBL.bl(Con{{w, r}}), List.append(&2, Bool, bb(VSP.bt(k, Con{{w, r}})), Y), bl2(k, Con{{w, r}}, FD.nat__succ_inj(List.length(&2, U32, Con{{w, r}}), 1n+k, hl)))
'''



def core_text():
    L = [r'''
# ---- the decoder's object: the last word masked, then the delimiter bit cleared ----

def pk7(c: Bool, +x: U32, +y: U32, +hx: {Nat.is_le(U32.to_nat(x), 7n) == True{} : Bool}, +hy: {Nat.is_le(U32.to_nat(y), 7n) == True{} : Bool})
    -> {Nat.is_le(U32.to_nat(O.pick(c, x, y)), 7n) == True{} : Bool}:
  match c:
    case True{}: hx
    case False{}: hy

def hb7(+v: U32) -> {Nat.is_le(VY.hb(v), 7n) == True{} : Bool}:
  pk7(U32.is_ge(v, 128), 7, O.pick(U32.is_ge(v, 64), 6, O.pick(U32.is_ge(v, 32), 5, O.pick(U32.is_ge(v, 16), 4, O.pick(U32.is_ge(v, 8), 3, O.pick(U32.is_ge(v, 4), 2, O.pick(U32.is_ge(v, 2), 1, 0)))))), {==},
    pk7(U32.is_ge(v, 64), 6, O.pick(U32.is_ge(v, 32), 5, O.pick(U32.is_ge(v, 16), 4, O.pick(U32.is_ge(v, 8), 3, O.pick(U32.is_ge(v, 4), 2, O.pick(U32.is_ge(v, 2), 1, 0))))), {==},
      pk7(U32.is_ge(v, 32), 5, O.pick(U32.is_ge(v, 16), 4, O.pick(U32.is_ge(v, 8), 3, O.pick(U32.is_ge(v, 4), 2, O.pick(U32.is_ge(v, 2), 1, 0)))), {==},
        pk7(U32.is_ge(v, 16), 4, O.pick(U32.is_ge(v, 8), 3, O.pick(U32.is_ge(v, 4), 2, O.pick(U32.is_ge(v, 2), 1, 0))), {==},
          pk7(U32.is_ge(v, 8), 3, O.pick(U32.is_ge(v, 4), 2, O.pick(U32.is_ge(v, 2), 1, 0)), {==},
            pk7(U32.is_ge(v, 4), 2, O.pick(U32.is_ge(v, 2), 1, 0), {==}, pk7(U32.is_ge(v, 2), 1, 0, {==}, {==})))))))

def s5z(+p: Nat, +hp: {Nat.is_lt(p, 32n) == True{} : Bool}) -> {VD.s_rng(5n, p) == 0n : Nat}:
  FD.nat__le_antisym(VD.s_rng(5n, p), 0n, C.rgm(5n, p, 31n, FD.nat__lt_succ_le(p, 31n, hp)), FD.nat__zero_le(VD.s_rng(5n, p)))

law s5q:
  for +Q: Nat
  for +p: Nat
  for +hp: {Nat.is_lt(p, 32n) == True{} : Bool}
  {VD.s_rng(5n, Nat.add(x32(Q), p)) == Q : Nat}
def s5q(Q, p, hp):
  match Q:
    case 0n: s5z(p, hp)
    case 1n+ +k: Equal.cong(Nat, Nat, z => 1n+z, VD.s_rng(5n, Nat.add(x32(k), p)), k, s5q(k, p, hp))

law x8q:
  for +Q: Nat
  {VSP.x8(A.quad(Q)) == x32(Q) : Nat}
def x8q(Q):
  match Q:
    case 0n: {==}
    case 1n+ +k: Equal.cong(Nat, Nat, z => 32n+z, VSP.x8(A.quad(k)), x32(k), x8q(k))
''']
    TH = 'FD.array__thaw(U32, M)'
    G = lambda arr: f'{{BK.btk(U32.to_nat(NB), BK.bitsof(FD.array__slots(U32, FD.array__freeze(U32, O.clear_bit({arr}, NB))))) == BK.btk(U32.to_nat(NB), BK.bitsof(FD.array__slots(U32, M))) : +List<Bool>}}'
