        eO = (f'Equal.trans({D}, o, T.SignedAggregateAndProof{{{P0}, y1}}, {O1}, es,\n'
              f'      Equal.cong(T.AggregateAndProof, {D}, z => T.SignedAggregateAndProof{{z, y1}}, {P0}, {AAP}, {eC}))')
