def hv_text():
    return ('\n'.join(HV_IMPORTS) + '''

# GENERATED by codegen/e2e_bridge.py (codegen/e2e_bview_gen.py). Do not edit.
# The bit-list decoders' objects satisfy the encode records' storage premise hv: the decoder copies the list's words
# into a tree M, keeps the bytes 0 .. p of the last word (mask_last) and clears the delimiter bit NB = 8 (n - 1) + h,
# h = high_bit(the last byte) (clear_bit). Every bit of the last word at or above NB is then clear (hvw0 .. hvw3: a
# case split on the last byte's bits, the other bits symbolic), and the result is a tree update of M (hcore, hvobj).
'''
            + HV_BASE.replace('@ANDT@', _hv_andt()) + '\n' + _hv_baz() + '\n' + _hv_word_lemmas()
            + HV_TREE.replace('@NLB@', _hv_nlb()).replace('@SPLIT32@', _hv_split32()) + _hv_cores() + _hv_objs() + HV_SDB)


def _hvq(t):
    import re as _re
    return _re.sub(r'(?<![\w.])(SDX|nu|cbt|pos5|pkX|hvw\d|nlb\d)\(', r'HV.\1(', t)


def hvk_text():
    return ('\n'.join(HV_IMPORTS) + '\nimport ./e2e_hv.bend as HV\n' + '''
# GENERATED by codegen/e2e_bridge.py (codegen/e2e_bview_gen.py). Do not edit.
# A copy that already masked its last word (vbytes' MK, vua_ct's CT) keeps it masked (kmkG, kct); the runtime's word
# read RD.wd is the tree slot (wd_slot), so the storage premise SDB follows from SDX (sdbw).
''' + _hvq(HV_CT.replace('@KMKROWS@', _hv_kmk_rows()) + HV_CT2))


def hvg_text():
    return ('\n'.join(HV_IMPORTS) + '\nimport ./e2e_hv.bend as HV\n' + '''
# GENERATED by codegen/e2e_bridge.py (codegen/e2e_bview_gen.py). Do not edit.
# hv on a copy CT whose last word is already masked (kf): clearing the delimiter bit NB = 8 (n - 1) + h leaves no bit
# set at or above NB (hcoreG0 .. 3; the same case split as e2e_hv's hcore).
''' + _hvq(_hv_coresG()))


def hvo_text():
    import re as _re
    return ('\n'.join(HV_IMPORTS) + '\nimport ./e2e_hv.bend as HV\nimport ./e2e_hvg.bend as HVG\n' + '''
# GENERATED by codegen/e2e_bridge.py (codegen/e2e_bview_gen.py). Do not edit.
# hvctobj: the bit list on a masked copy CT, its delimiter cleared, satisfies SDX (a case split on n's low bits, then hcoreG).
''' + _re.sub(r'(?<![\w.])hcoreG(\d)\(', r'HVG.hcoreG\1(', _hvq(_hv_objsG())))


# ---- the same for a storage the copy already masked (vua_ct's CT = vbytes' MK over the copy) ----
HV_CT = r'''
# masking the last word twice is masking it once
def kk1(+y: U32) -> {O.keep(1, O.keep(1, y)) == O.keep(1, y) : U32}: VYS.and_assoc(y, 255, 255)
def kk2(+y: U32) -> {O.keep(2, O.keep(2, y)) == O.keep(2, y) : U32}: VYS.and_assoc(y, 65535, 65535)
def kk3(+y: U32) -> {O.keep(3, O.keep(3, y)) == O.keep(3, y) : U32}: VYS.and_assoc(y, 16777215, 16777215)

# the masked storage's last word is masked
def kmkG(+L: U32, +dz: Nat, +C_: FD.array__Tree<U32>, +pf: {FD.array__perfect(U32, dz, C_) == True{} : Bool}, +hy: {Nat.is_le(VC.YL(L), U32.to_nat(VB.UMAX())) == True{} : Bool}, +hr: {Nat.is_le(VC.NW(L), VB.pw(dz)) == True{} : Bool})
    -> {VB.slot(VBY.MK(L, dz, C_), VBY.KW(L)) == O.keep(VBY.RM(L), VB.slot(VBY.MK(L, dz, C_), VBY.KW(L))) : U32}:
  match L:
@KMKROWS@
'''


def _hv_kmk_rows():
    out = []
    for r in range(4):
        c = [bool(r & 1), bool(r & 2)]
        X = f'U32{{WCon{{{B(c[0])}, WCon{{{B(c[1])}, r}}}}}}'
        Xp = f'U32{{WCon{{{B(c[0])}, WCon{{{B(c[1])}, +r}}}}}}'
        RLW = f'U32{{WCon{{{B(c[0])}, WCon{{{B(c[1])}, Word.zero(30n)}}}}}}'
        ls = f'BF.low_sel({B(c[0])}, {B(c[1])}, r)'
        mk = lambda b: f'VBY.mk({b}, {X}, dz, C_)'
        if r == 0:
            out.append(f'''    case {Xp}:
      %Equal.sym(U32, U32.and({X}, 3), {RLW}, Equal.sym(U32, {RLW}, U32.and({X}, 3), {ls})) :
        {{VB.slot(VBY.mk(U32.is_eq(_, 0), {X}, dz, C_), VBY.KW({X})) == O.keep(_, VB.slot(VBY.mk(U32.is_eq(_, 0), {X}, dz, C_), VBY.KW({X}))) : U32}}
      {{==}}''')
        else:
            v = f'O.keep(VBY.RM({X}), VB.slot(C_, VBY.KW({X})))'
            out.append(f'''    case {Xp}:
      +e0 = FD.logic__subst(U32, z => {{U32.is_eq(z, 0) == False{{}} : Bool}}, {RLW}, U32.and({X}, 3), {ls}, {{==}})
      +hkw = VBY.kw_ltU({X}, dz, hy, e0, hr)
      +e1 = Equal.trans(U32, VB.slot({mk('False{}')}, VBY.KW({X})), FD.flat__nthc(FD.spec_common__update(U32, FD.array__slots(U32, C_), VBY.KW({X}), {v}), VBY.KW({X})), {v},
        Equal.cong(List<&2, U32>, U32, z => FD.flat__nthc(z, VBY.KW({X})), FD.array__slots(U32, {mk('False{}')}), FD.spec_common__update(U32, FD.array__slots(U32, C_), VBY.KW({X}), {v}),
          FD.array__upd_slots(U32, dz, C_, VBY.KW({X}), {v}, hkw, pf)),
        nu(FD.array__slots(U32, C_), VBY.KW({X}), {v}, FD.array__len_lt(U32, dz, C_, VBY.KW({X}), pf, hkw)))
      %Equal.sym(Bool, U32.is_eq(VBY.RM({X}), 0), False{{}}, e0) :
        {{VB.slot(VBY.mk(_, {X}, dz, C_), VBY.KW({X})) == O.keep(VBY.RM({X}), VB.slot(VBY.mk(_, {X}, dz, C_), VBY.KW({X}))) : U32}}
      %Equal.sym(U32, VB.slot({mk('False{}')}, VBY.KW({X})), {v}, e1) : {{_ == O.keep(VBY.RM({X}), _) : U32}}
      %Equal.sym(U32, U32.and({X}, 3), {RLW}, Equal.sym(U32, {RLW}, U32.and({X}, 3), {ls})) :
        {{O.keep(_, VB.slot(C_, VBY.KW({X}))) == O.keep(_, O.keep(_, VB.slot(C_, VBY.KW({X})))) : U32}}
      Equal.sym(U32, O.keep({r}, O.keep({r}, VB.slot(C_, VBY.KW({X})))), O.keep({r}, VB.slot(C_, VBY.KW({X}))), kk{r}(VB.slot(C_, VBY.KW({X}))))''')
    return '\n'.join(out) + '\n'


HV_CT2 = r'''
# vua_ct's copy is masked storage (either copy: aligned or shifted)
def kct(+r: Nat, +d: Nat, +t: FD.array__Tree<U32>, +off: U32, +L: U32, +dz: Nat, +hy: {Nat.is_le(VC.YL(L), U32.to_nat(VB.UMAX())) == True{} : Bool}, +hr: {Nat.is_le(VC.NW(L), VB.pw(dz)) == True{} : Bool})
    -> {VB.slot(UCT.cts(r, d, t, off, L, dz), VBY.KW(L)) == O.keep(VBY.RM(L), VB.slot(UCT.cts(r, d, t, off, L, dz), VBY.KW(L))) : U32}:
  match r:
    case 0n: kmkG(L, dz, VB.mone(VC.NW(L), VR.QX(off), 0n, dz, VC.ZT(dz), t), VB.mone_perfect(VC.NW(L), VR.QX(off), 0n, dz, VC.ZT(dz), t, FD.array__trep_perfect(U32, dz, 0)), hy, hr)
    case 1n+ +q: kmkG(L, dz, UC.smone(1n+q, VC.NW(L), VR.QX(off), 0n, dz, d, VC.ZT(dz), t), UC.smone_perfect(1n+q, VC.NW(L), VR.QX(off), 0n, dz, d, VC.ZT(dz), t, FD.array__trep_perfect(U32, dz, 0)), hy, hr)

# the storage's words read as the runtime reads them (RD.wd) are its slots
def wd_slot(+d: Nat, +t: FD.array__Tree<U32>, +q: U32, +i: Nat, +eq: {U32.to_nat(q) == i : Nat}, +hd: {Nat.is_lt(d, 31n) == True{} : Bool},
    +hi: {Nat.is_lt(i, VB.pw(d)) == True{} : Bool}, +pf: {FD.array__perfect(U32, d, t) == True{} : Bool}) -> {RD.wd(t, d, q) == VB.slot(t, i) : U32}:
  +e = Equal.trans(Array<U32> & U32, (FD.array__thaw(U32, t), RD.wd(t, d, q)), Array.get(U32, FD.array__thaw(U32, t), q), (FD.array__thaw(U32, t), VB.slot(t, i)),
    Equal.sym(Array<U32> & U32, Array.get(U32, FD.array__thaw(U32, t), q), (FD.array__thaw(U32, t), RD.wd(t, d, q)), VE.get_any(d, t, q, VB.lt32(d, hd), pf)),
    VB.get_n(d, t, q, i, eq, VB.lt32(d, hd), hi, pf))
  Equal.cong(Array<U32> & U32, U32, p => Pair.snd(Array<U32>, U32, p), (FD.array__thaw(U32, t), RD.wd(t, d, q)), (FD.array__thaw(U32, t), VB.slot(t, i)), e)

# a window ending by NMAX ends below 2^32
def hwN32(+x: Nat, +len: U32, +hwN: {Nat.is_le(Nat.add(x, U32.to_nat(len)), U32.to_nat(VB.NMAX())) == True{} : Bool}) -> {Nat.is_lt(Nat.add(x, U32.to_nat(len)), FD.spec_common__pow2(32n)) == True{} : Bool}:
  VB.umax_lt(Nat.add(x, U32.to_nat(len)), FD.nat__le_trans(Nat.add(x, U32.to_nat(len)), U32.to_nat(VB.NMAX()), U32.to_nat(VB.UMAX()), hwN,
    FD.logic__subst(Bool, z => {z == True{} : Bool}, U32.is_le(VB.NMAX(), VB.UMAX()), Nat.is_le(U32.to_nat(VB.NMAX()), U32.to_nat(VB.UMAX())), VB.le_u32n(VB.NMAX(), VB.UMAX()), {==})))

# the hv part of the storage premise of a bit list of any depth
def SDXE(o: O.Bits) -> Data: DK.Ex(Nat, dz => SDXO(o, dz))

# the storage premise with the runtime's word read (e2e_bsenc.SDB / e2e_pbs.SDB / e2e_bbatt.SDB have this body)
def SDBW(o: O.Bits, +Kd: Nat) -> Data:
  DK.Ex(FD.array__Tree<U32>, T => DK.Ex(Nat, dw => DK.Ex(U32, K => DK.P2({o == O.Bits{FD.array__thaw(U32, T), K} : O.Bits},
    DK.P2({FD.array__perfect(U32, dw, T) == True{} : Bool},
    DK.P2({Nat.is_lt(dw, Kd) == True{} : Bool},
    DK.P2({Nat.is_le(Nat.add(U32.to_nat(U32.shrn(K, 5n)), 1n), VB.pw(dw)) == True{} : Bool},
    {O.bits_above_zero(U32.and(K, 31), RD.wd(T, dw, U32.shrn(K, 5n))) == True{} : Bool})))))))

# the hv part of the storage premise, for the bit list o (whatever the size bounds of the premise it goes into)
def SDXO(o: O.Bits, +dz: Nat) -> Data:
  DK.Ex(FD.array__Tree<U32>, T => DK.Ex(U32, K => DK.P2({o == O.Bits{FD.array__thaw(U32, T), K} : O.Bits},
    DK.P2({FD.array__perfect(U32, dz, T) == True{} : Bool},
    DK.P2({Nat.is_le(Nat.add(U32.to_nat(U32.shrn(K, 5n)), 1n), VB.pw(dz)) == True{} : Bool},
          {O.bits_above_zero(U32.and(K, 31), VB.slot(T, U32.to_nat(U32.shrn(K, 5n)))) == True{} : Bool})))))

def sdxo(-o: O.Bits, -A_: Array<U32>, +K: U32, +dz: Nat, +eo: {o == O.Bits{A_, K} : O.Bits}, +x: HV.SDX(A_, K, dz)) -> SDXO(o, dz):
  (+T, x1) = x
  (+eA, x2) = x1
  (T, (K, (Equal.trans(O.Bits, o, O.Bits{A_, K}, O.Bits{FD.array__thaw(U32, T), K}, eo, Equal.cong(Array<U32>, O.Bits, z => O.Bits{z, K}, A_, FD.array__thaw(U32, T), eA)), x2)))

def sdbw(-A_: Array<U32>, +K: U32, +dz: Nat, +Kd: Nat, +hd: {Nat.is_lt(dz, Kd) == True{} : Bool}, +hd31: {Nat.is_lt(dz, 31n) == True{} : Bool}, +x: SDX(A_, K, dz)) -> SDBW(O.Bits{A_, K}, Kd):
  (+T, x1) = x
  (+eA, x2) = x1
  (+pT, x3) = x2
  (+hr, +hv) = x3
  +hi = FD.nat__succ_le_lt(U32.to_nat(U32.shrn(K, 5n)), VB.pw(dz), FD.logic__subst(Nat, z => {Nat.is_le(z, VB.pw(dz)) == True{} : Bool}, Nat.add(U32.to_nat(U32.shrn(K, 5n)), 1n), 1n+U32.to_nat(U32.shrn(K, 5n)), FD.nat__add_comm(U32.to_nat(U32.shrn(K, 5n)), 1n), hr))
  (T, (dz, (K, (Equal.cong(Array<U32>, O.Bits, z => O.Bits{z, K}, A_, FD.array__thaw(U32, T), eA), (pT, (hd, (hr,
    FD.logic__subst(U32, z => {O.bits_above_zero(U32.and(K, 31), z) == True{} : Bool}, VB.slot(T, U32.to_nat(U32.shrn(K, 5n))), RD.wd(T, dz, U32.shrn(K, 5n)),
      Equal.sym(U32, RD.wd(T, dz, U32.shrn(K, 5n)), VB.slot(T, U32.to_nat(U32.shrn(K, 5n))), wd_slot(dz, T, U32.shrn(K, 5n), U32.to_nat(U32.shrn(K, 5n)), {==}, hd31, hi, pT)), hv))))))))
'''


def _hv_coresG():
    """hcoreG0 .. 3: hcore on a storage T0 whose word Q is the kept bytes of x (the mask already applied)."""
    L = []
    for p in range(4):
        r = (p + 1) % 4
        P = f'Nat.add({8 * p}n, h)'
        J = 'U32.to_nat(U32.shrn(NB, 5n))'
        KX = HV_KEEP[p].replace('@X@', 'x').replace('O.keep(1,', 'O.keep(1,').strip()
        NOTB = 'U32.not(M.shl_by(1, U32.and(NB, 31)))'
        V0 = f'U32.and(FD.flat__nthc(FD.array__slots(U32, T0), {J}), {NOTB})'
        T = f'FD.array__upd(U32, dz, T0, {J}, {V0})'
        A = 'O.clear_bit(FD.array__thaw(U32, T0), NB)'
        L.append(f'''
def hcoreG{p}(+dz: Nat, +T0: FD.array__Tree<U32>, +NB: U32, +Q: Nat, +h: Nat, +pf: {{FD.array__perfect(U32, dz, T0) == True{{}} : Bool}},
    +hdz: {{Nat.is_lt(dz, 32n) == True{{}} : Bool}}, +hh: {{Nat.is_le(h, 7n) == True{{}} : Bool}},
    +eNB: {{U32.to_nat(NB) == Nat.add(BV.x32(Q), {P}) : Nat}}, +hq: {{Nat.is_lt(Q, FD.spec_common__pow2(dz)) == True{{}} : Bool}},
    +x: U32, +eX: {{FD.flat__nthc(FD.array__slots(U32, T0), Q) == {KX} : U32}}, +eb: {{VY.hb({HV_BYTE[p].replace('@X@', 'x')}) == h : Nat}}) -> SDX({A}, NB, dz):
  +hp32 = FD.nat__le_lt_trans({P}, {8 * p + 7}n, 32n, Order.add_left({8 * p}n, h, 7n, hh), {{==}})
  +e5 = Equal.trans(Nat, {J}, VD.s_rng(5n, U32.to_nat(NB)), Q, VD.shrk(5n, NB),
    Equal.trans(Nat, VD.s_rng(5n, U32.to_nat(NB)), VD.s_rng(5n, Nat.add(BV.x32(Q), {P})), Q, Equal.cong(Nat, Nat, z => VD.s_rng(5n, z), U32.to_nat(NB), Nat.add(BV.x32(Q), {P}), eNB), BV.s5q(Q, {P}, hp32)))
  +hq5 = FD.logic__subst(Nat, z => {{Nat.is_lt(z, FD.spec_common__pow2(dz)) == True{{}} : Bool}}, Q, {J}, Equal.sym(Nat, {J}, Q, e5), hq)
  +pT = FD.array__upd_perfect(U32, dz, T0, {J}, {V0}, pf)
  +hr = FD.logic__subst(Nat, z => {{Nat.is_le(z, VB.pw(dz)) == True{{}} : Bool}}, 1n+{J}, Nat.add({J}, 1n), FD.nat__add_comm(1n, {J}), FD.nat__lt_succ_le_succ({J}, VB.pw(dz), hq5))
  +eS0 = Equal.trans(U32, VB.slot({T}, {J}), FD.flat__nthc(FD.spec_common__update(U32, FD.array__slots(U32, T0), {J}, {V0}), {J}), {V0},
    Equal.cong(List<&2, U32>, U32, z => FD.flat__nthc(z, {J}), FD.array__slots(U32, {T}), FD.spec_common__update(U32, FD.array__slots(U32, T0), {J}, {V0}), FD.array__upd_slots(U32, dz, T0, {J}, {V0}, hq5, pf)),
    nu(FD.array__slots(U32, T0), {J}, {V0}, FD.array__len_lt(U32, dz, T0, {J}, pf, hq5)))
  +eS = Equal.trans(U32, VB.slot({T}, {J}), {V0}, U32.and({KX}, {NOTB}), eS0,
    Equal.cong(U32, U32, z => U32.and(z, {NOTB}), FD.flat__nthc(FD.array__slots(U32, T0), {J}), {KX},
      FD.logic__subst(Nat, z => {{FD.flat__nthc(FD.array__slots(U32, T0), z) == {KX} : U32}}, Q, {J}, Equal.sym(Nat, {J}, Q, e5), eX)))
  +ec = pos5(NB, Q, {P}, e5, eNB, hp32)
  +ea = Equal.trans(Nat, U32.to_nat(U32.and(NB, 31)), {P}, Nat.add({8 * p}n, U32.to_nat(O.high_bit({HV_BYTE[p].replace('@X@', 'x')}))), ec,
    Equal.cong(Nat, Nat, z => Nat.add({8 * p}n, z), h, U32.to_nat(O.high_bit({HV_BYTE[p].replace('@X@', 'x')})), Equal.sym(Nat, VY.hb({HV_BYTE[p].replace('@X@', 'x')}), h, eb)))
  +hv = FD.logic__subst(U32, z => {{O.bits_above_zero(U32.and(NB, 31), z) == True{{}} : Bool}}, U32.and({KX}, {NOTB}), VB.slot({T}, {J}), Equal.sym(U32, VB.slot({T}, {J}), U32.and({KX}, {NOTB}), eS),
    hvw{p}(x, U32.and(NB, 31), ea))
  pkX({A}, NB, dz, {T}, cbt(dz, T0, NB, pf, hdz, hq5), pT, hr, hv)
''')
    return ''.join(L)


def _hv_objsG():
    """hvctobj: hvobj for a storage CT whose last word the copy already masked (kf), the bit list clear_bit(thaw CT, NB)."""
    HYP = ('+dz: Nat, +CT: FD.array__Tree<U32>, +NB: U32, +m: Nat, +h: Nat, +pf: {FD.array__perfect(U32, dz, CT) == True{} : Bool}, '
           '+hdz: {Nat.is_lt(dz, 32n) == True{} : Bool}, +hh: {Nat.is_le(h, 7n) == True{} : Bool}, '
           '+eNB: {U32.to_nat(NB) == Nat.add(VSP.x8(m), h) : Nat}, +hN: {Nat.is_le(C.nwn(U32.to_nat(n)), FD.spec_common__pow2(dz)) == True{} : Bool}, '
           '+hn3: {Nat.is_lt(Nat.add(3n, U32.to_nat(n)), FD.spec_common__pow2(32n)) == True{} : Bool}, +e1: {U32.to_nat(n) == 1n+m : Nat}, '
           '+eh: {VY.hb(VBL.nthb(SF.limbs(FD.array__slots(U32, CT)), m)) == h : Nat}, '
           '+kf: {VB.slot(CT, VBY.KW(n)) == O.keep(VBY.RM(n), VB.slot(CT, VBY.KW(n))) : U32}')
    G = 'SDX(O.clear_bit(FD.array__thaw(U32, CT), NB), NB, dz)'
    LM = 'SF.limbs(FD.array__slots(U32, CT))'
    L, cases = [], []

    def ebt(p, Q, ind='  '):
        B_ = HV_BYTE[p].replace('@X@', f'VB.slot(CT, {Q})')
        s_ = (f'+hlen = FD.array__len_lt(U32, dz, CT, {Q}, pf, hq)\n'
              f'+eh2 = FD.logic__subst(Nat, z => {{VY.hb(VBL.nthb({LM}, z)) == h : Nat}}, m, Nat.add({p}n, A.quad({Q})), em, eh)\n'
              f'+eb = Equal.trans(Nat, VY.hb({B_}), VY.hb(VBL.nthb({LM}, Nat.add({p}n, A.quad({Q})))), h,\n'
              f'  Equal.cong(U32, Nat, z => VY.hb(z), {B_}, VBL.nthb({LM}, Nat.add({p}n, A.quad({Q}))), Equal.sym(U32, VBL.nthb({LM}, Nat.add({p}n, A.quad({Q}))), {B_}, nlb{p}(FD.array__slots(U32, CT), {Q}, hlen))), eh2)\n')
        return ''.join(ind + l + '\n' for l in s_.rstrip('\n').split('\n'))

    def exf(p, N, Q, c, ind='  '):
        if p == 3:
            return f'{ind}+eX = {{{{==}} : {{VB.slot(CT, {Q}) == VB.slot(CT, {Q}) : U32}}}}\n'
        RLW = f'U32{{WCon{{{B(c[0])}, WCon{{{B(c[1])}, Word.zero(30n)}}}}}}'
        return (f'{ind}+kf1 = FD.logic__subst(Nat, z => {{VB.slot(CT, z) == O.keep(VBY.RM({N}), VB.slot(CT, z)) : U32}}, VBY.KW({N}), {Q}, ei, kf)\n'
                f'{ind}+eX = FD.logic__subst(U32, z => {{VB.slot(CT, {Q}) == O.keep(z, VB.slot(CT, {Q})) : U32}}, U32.and({N}, 3), {RLW}, Equal.sym(U32, {RLW}, U32.and({N}, 3), BF.low_sel({B(c[0])}, {B(c[1])}, r)), kf1)\n')
    for r in (1, 2, 3):
        p = r - 1
        c = [bool(r & 1), bool(r & 2)]
        N = f'U32{{WCon{{{B(c[0])}, WCon{{{B(c[1])}, r}}}}}}'
        Np = f'U32{{WCon{{{B(c[0])}, WCon{{{B(c[1])}, +r}}}}}}'
        Q = 'Word.to_nat(30n, r)'
        K = 8 * p
        L.append(f'''
def hvcn{r}(+r: Word(30n), {HYP.replace('U32.to_nat(n)', f'U32.to_nat({N})').replace('VBY.KW(n)', f'VBY.KW({N})').replace('VBY.RM(n)', f'VBY.RM({N})')})
    -> {G}:
  +em = FD.nat__succ_inj(m, Nat.add({p}n, A.quad({Q})), Equal.sym(Nat, U32.to_nat({N}), 1n+m, e1))
  +eNB2 = Equal.trans(Nat, U32.to_nat(NB), Nat.add(VSP.x8(m), h), Nat.add(BV.x32({Q}), Nat.add({K}n, h)), eNB,
    Equal.trans(Nat, Nat.add(VSP.x8(m), h), Nat.add(Nat.add({K}n, BV.x32({Q})), h), Nat.add(BV.x32({Q}), Nat.add({K}n, h)),
      Equal.cong(Nat, Nat, z => Nat.add(z, h), VSP.x8(m), Nat.add({K}n, BV.x32({Q})),
        Equal.trans(Nat, VSP.x8(m), VSP.x8(Nat.add({p}n, A.quad({Q}))), Nat.add({K}n, BV.x32({Q})), Equal.cong(Nat, Nat, z => VSP.x8(z), m, Nat.add({p}n, A.quad({Q})), em),
          Equal.cong(Nat, Nat, z => Nat.add({K}n, z), VSP.x8(A.quad({Q})), BV.x32({Q}), BV.x8q({Q})))),
      BV.alg3({K}n, BV.x32({Q}), h)))
  +y = U32.shrn(({N} + 3 : U32), 2n)
  +ey = Equal.trans(Nat, U32.to_nat(y), VD.s_rng(2n, U32.to_nat(({N} + 3 : U32))), 1n+{Q}, VD.shrk(2n, ({N} + 3 : U32)),
    Equal.trans(Nat, VD.s_rng(2n, U32.to_nat(({N} + 3 : U32))), C.nwn(Nat.add({r}n, A.quad({Q}))), 1n+{Q},
      Equal.cong(Nat, Nat, z => VD.s_rng(2n, z), U32.to_nat(({N} + 3 : U32)), Nat.add(3n, U32.to_nat({N})), VB.add_lt32({N}, 3, U32.to_nat({N}), {{==}}, hn3)), BV.nwr{r}({Q})))
  +ei = Equal.trans(Nat, U32.to_nat(U32.sub(y, 1)), Nat.sub(U32.to_nat(y), 1n), {Q},
    FD.u32__sub_nat(y, 1, FD.logic__subst(Nat, z => {{Nat.is_le(1n, z) == True{{}} : Bool}}, 1n+{Q}, U32.to_nat(y), Equal.sym(Nat, U32.to_nat(y), 1n+{Q}, ey), FD.nat__zero_le({Q}))),
    Equal.trans(Nat, Nat.sub(U32.to_nat(y), 1n), Nat.sub(1n+{Q}, 1n), {Q}, Equal.cong(Nat, Nat, z => Nat.sub(z, 1n), U32.to_nat(y), 1n+{Q}, ey), FD.list__sub_zero_eq({Q})))
  +hq = FD.nat__succ_le_lt({Q}, FD.spec_common__pow2(dz), FD.logic__subst(Nat, z => {{Nat.is_le(z, FD.spec_common__pow2(dz)) == True{{}} : Bool}}, C.nwn(U32.to_nat({N})), 1n+{Q}, BV.nwr{r}({Q}), hN))
{ebt(p, Q)}{exf(p, N, Q, c)}  hcoreG{p}(dz, CT, NB, {Q}, h, pf, hdz, hh, eNB2, hq, VB.slot(CT, {Q}), eX, eb)
''')
        cases.append(f'    case {Np}: hvcn{r}(r, dz, CT, NB, m, h, pf, hdz, hh, eNB, hN, hn3, e1, eh, kf)')
    N0 = 'U32{WCon{False{}, WCon{False{}, r}}}'
    L.append(f'''
def hvcn0q(+r: Word(30n), +Qn: Nat, +eq: {{Word.to_nat(30n, r) == Qn : Nat}}, {HYP.replace('U32.to_nat(n)', f'U32.to_nat({N0})').replace('VBY.KW(n)', f'VBY.KW({N0})').replace('VBY.RM(n)', f'VBY.RM({N0})')})
    -> {G}:
  match Qn:
    case 0n: Empty.absurd({G}, FD.nat__succ_zero(m, Equal.sym(Nat, 0n, 1n+m, FD.logic__subst(Nat, z => {{A.quad(z) == 1n+m : Nat}}, Word.to_nat(30n, r), 0n, eq, e1))))
    case 1n+ +Q:
      +em = FD.nat__succ_inj(m, Nat.add(3n, A.quad(Q)), Equal.sym(Nat, A.quad(1n+Q), 1n+m, FD.logic__subst(Nat, z => {{A.quad(z) == 1n+m : Nat}}, Word.to_nat(30n, r), 1n+Q, eq, e1)))
      +eNB2 = Equal.trans(Nat, U32.to_nat(NB), Nat.add(VSP.x8(m), h), Nat.add(BV.x32(Q), Nat.add(24n, h)), eNB,
        Equal.trans(Nat, Nat.add(VSP.x8(m), h), Nat.add(Nat.add(24n, BV.x32(Q)), h), Nat.add(BV.x32(Q), Nat.add(24n, h)),
          Equal.cong(Nat, Nat, z => Nat.add(z, h), VSP.x8(m), Nat.add(24n, BV.x32(Q)),
            Equal.trans(Nat, VSP.x8(m), VSP.x8(Nat.add(3n, A.quad(Q))), Nat.add(24n, BV.x32(Q)), Equal.cong(Nat, Nat, z => VSP.x8(z), m, Nat.add(3n, A.quad(Q)), em),
              Equal.cong(Nat, Nat, z => Nat.add(24n, z), VSP.x8(A.quad(Q)), BV.x32(Q), BV.x8q(Q)))),
          BV.alg3(24n, BV.x32(Q), h)))
      +hq = FD.nat__succ_le_lt(Q, FD.spec_common__pow2(dz), FD.logic__subst(Nat, z => {{Nat.is_le(z, FD.spec_common__pow2(dz)) == True{{}} : Bool}}, C.nwn(U32.to_nat({N0})), 1n+Q,
        Equal.trans(Nat, C.nwn(U32.to_nat({N0})), Word.to_nat(30n, r), 1n+Q, C.rq(Word.to_nat(30n, r)), eq), hN))
{ebt(3, 'Q', '      ')}{exf(3, N0, 'Q', None, '      ')}      hcoreG3(dz, CT, NB, Q, h, pf, hdz, hh, eNB2, hq, VB.slot(CT, Q), eX, eb)
''')
    cases.insert(0, f'    case U32{{WCon{{False{{}}, WCon{{False{{}}, +r}}}}}}: hvcn0q(r, Word.to_nat(30n, r), {{==}}, dz, CT, NB, m, h, pf, hdz, hh, eNB, hN, hn3, e1, eh, kf)')
    L.append(f'''
# The bit list on a masked copy CT (vua_ct / vbytes' MK: its last word already masked, kf), the delimiter bit NB cleared,
# NB = 8 m + h, n = 1 + m, h the high bit of the last byte: a tree at CT's depth with room for word NB >> 5, no bit set at or above NB.
def hvctobj(+n: U32, {HYP}) -> {G}:
  match n:
''' + '\n'.join(cases) + '\n')
    return ''.join(L)


HV_SDB = r'''
# ---- as the encode laws' premise forms ----
# word K >> 5 as the bit-list records index it
def qk5(+K: U32) -> {U32.to_nat(U32.shrn(K, 5n)) == VBT.QK(K) : Nat}:
  %Equal.sym(U32, U32.add(0, U32.shrn(K, 3n)), U32.shrn(K, 3n), FD.u32alg__zero_add(U32.shrn(K, 3n))) : {U32.to_nat(U32.shrn(K, 5n)) == U32.to_nat(U32.shrn(_, 2n)) : Nat}
  Equal.trans(Nat, U32.to_nat(U32.shrn(K, 5n)), VD.s_rng(5n, U32.to_nat(K)), U32.to_nat(U32.shrn(U32.shrn(K, 3n), 2n)), VD.shrk(5n, K),
    Equal.sym(Nat, U32.to_nat(U32.shrn(U32.shrn(K, 3n), 2n)), VD.s_rng(5n, U32.to_nat(K)),
      Equal.trans(Nat, U32.to_nat(U32.shrn(U32.shrn(K, 3n), 2n)), VD.s_rng(2n, U32.to_nat(U32.shrn(K, 3n))), VD.s_rng(5n, U32.to_nat(K)), VD.shrk(2n, U32.shrn(K, 3n)),
        Equal.cong(Nat, Nat, z => VD.s_rng(2n, z), U32.to_nat(U32.shrn(K, 3n)), VD.s_rng(3n, U32.to_nat(K)), VD.shrk(3n, K)))))

# the bit list's storage as e2e_bitv.sdbv (depth below 31)
def sdbx(-A_: Array<U32>, +K: U32, +dz: Nat, +hd: {Nat.is_lt(dz, 31n) == True{} : Bool}, +x: SDX(A_, K, dz)) -> BTV.sdbv(O.Bits{A_, K}):
  (+T, x1) = x
  (+eA, x2) = x1
  (+pT, x3) = x2
  (+hr, +hv) = x3
  (T, (dz, (K, (Equal.cong(Array<U32>, O.Bits, z => O.Bits{z, K}, A_, FD.array__thaw(U32, T), eA), (pT, (hd, (hr,
    FD.logic__subst(Nat, z => {O.bits_above_zero(U32.and(K, 31), VB.slot(T, z)) == True{} : Bool}, U32.to_nat(U32.shrn(K, 5n)), VBT.QK(K), qk5(K), hv))))))))
'''
